<script lang="ts">
 import type { MunicipalityFilters } from '../types/park'; import { defaultMunicipalityFilters,municipalityFilterCount } from '../lib/municipality';
 let {filters=$bindable(),resultCount,open,onClose}:{filters:MunicipalityFilters;resultCount:number;open:boolean;onClose:()=>void}=$props();
 const items=[['noBench','No bench'],['noToilet','No toilet'],['noWaterTapAccess','No water tap'],['noWheelchairAccessible','No wheelchair accessibility'],['noPlayground','No playground'],['noPublicSportPark','No public sport park'],['noFootballSportCourts','No football / sport courts'],['noDogOffLeashArea','No dog off-leash area'],['noCrossings','No crossings'],['noTrafficLight','No traffic light'],['noStreetParkLight','No street / park lighting'],['noFencedArea','No fenced area']] as const;
</script>
{#if open}<button class="scrim" aria-label="Close filters" onclick={onClose}></button>{/if}<aside class:open class="municipality-filters" aria-label="Municipality investigation filters"><div class="filter-head"><div><p class="eyebrow">Investigation filters</p><h2>Explore recorded gaps</h2></div><button class="close" onclick={onClose} aria-label="Close filters">×</button></div><div class="result-row"><strong>{resultCount} parks</strong><span>shown on map</span></div><form class="filter-form"><details open><summary>Recorded facility gaps</summary><fieldset>{#each items as item}<label class="check"><input type="checkbox" bind:checked={filters[item[0]]}/><span>{item[1]}</span></label>{/each}</fieldset></details><details open><summary>Greenery & access</summary><fieldset>{#each [['canopyCover','Canopy cover'],['grassCover','Grass cover']] as group}<div class="radio-group"><span>{group[1]}</span><div class="segments">{#each ['any','low','mid','high'] as option}<label><input type="radio" name={`municipal-${group[0]}`} value={option} bind:group={filters[group[0] as 'canopyCover'|'grassCover']}/><span>{option[0].toUpperCase()+option.slice(1)}</span></label>{/each}</div></div>{/each}<div class="radio-group"><span>Public access</span><div class="segments three">{#each [['any','Any'],['anytime','Anytime'],['restricted','Restricted']] as option}<label><input type="radio" name="municipal-access" value={option[0]} bind:group={filters.publicAccess}/><span>{option[1]}</span></label>{/each}</div></div></fieldset></details></form><button class="clear" onclick={()=>filters={...defaultMunicipalityFilters}} disabled={municipalityFilterCount(filters)===0}>Reset investigation filters</button></aside>
